function updateFilterSelect(selectId, values) {
  const select = document.getElementById(selectId);
  const currentValue = select.value;

  select.innerHTML = '<option value="">الكل</option>';
  values.forEach(value => {
    select.innerHTML += `<option value="${value}">${value}</option>`;
  });

  if (values.includes(currentValue)) {
    select.value = currentValue;
  }
}

function applyFilters() {
  const emailFilter = document.getElementById('filter-email').value;
  const usernameFilter = document.getElementById('filter-username').value;
  const pageNameFilter = document.getElementById('filter-pagename').value;
  const supervisorFilter = document.getElementById('filter-supervisor').value;
  const rangeFilter = document.getElementById('filter-range').value;
  const searchText = document.getElementById('search-input').value.toLowerCase();

  filteredUsers = allUsers.filter(user => {
    const matchEmail = !emailFilter || user.email === emailFilter;
    const matchUsername = !usernameFilter || user.username === usernameFilter;
    const matchPageName = !pageNameFilter || user.pageName === pageNameFilter;
    const matchSupervisor = !supervisorFilter || user.supervisor === supervisorFilter;
    const matchRange = !rangeFilter || user.rangeKey === rangeFilter;
    const matchSearch = !searchText || 
      user.email.toLowerCase().includes(searchText) ||
      user.username.toLowerCase().includes(searchText) ||
      user.mobile.toLowerCase().includes(searchText) ||
      user.pageName.toLowerCase().includes(searchText) ||
      user.supervisor.toLowerCase().includes(searchText);

    return matchEmail && matchUsername && matchPageName && matchSupervisor && matchRange && matchSearch;
  });

  renderUsersTable();
}

