// 🎛️ فلاتر متعددة المستويات (معيار حيدر) — إضافة 2026-11
// المستويات: الفريق ← المشرفة ← الصفحة، وفلاتر الحالة والصلاحية، وبحث عربي موحّد
// ====================================
const UNC = 'غير مصنّف';
let MF = { team: [], sup: [], page: [], range: [], status: [], perm: [], q: '' };
let MF_SORT = { key: '', dir: 1 };
let MF_MORE = {};
try { const sv = JSON.parse(localStorage.getItem('perm_mf2') || 'null'); if (sv) MF = Object.assign(MF, sv); } catch (e) {}
function mfSave() { try { localStorage.setItem('perm_mf2', JSON.stringify(MF)); } catch (e) {} }

const MF_STATUS = [
  { k: 'fix', l: '⚠️ يحتاج تصحيح', c: 'red', t: s => s.page || s.sup },
  { k: 'page', l: 'الصفحة غلط', c: 'orange', t: s => s.page },
  { k: 'sup', l: 'المشرف غلط', c: 'orange', t: s => s.sup && !s.mismatch && !s.delegate },
  { k: 'delegate', l: 'بخانة المشرف مندوبة', c: 'orange', t: s => s.delegate },
  { k: 'mismatch', l: 'المشرفة ما تطابق الصفحة', c: 'orange', t: s => s.mismatch },
  { k: 'ok', l: '✅ سليم', c: 'green', t: s => !s.page && !s.sup }
];
const MF_PERM = [ { k: 'delegate', l: '👤 مندوب' }, { k: 'supervisor', l: '👨‍💼 مشرف' }, { k: 'warehouse', l: '📦 مخزن' } ];

function uSup(u) { const s = String(u.supervisor || '').trim(); return PICK.supSet.has(s) ? s : UNC; }
function uPage(u) { const p = String(u.pageName || '').trim(); return PICK.pageSet.has(p) ? p : UNC; }
function uTeam(u) {
  const s = uSup(u);
  if (s === UNC) return UNC;
  if (/الادارة/.test(s)) return 'الإدارة';
  return (PICK.managers && PICK.managers[s]) || s;
}
// يطابق كل الفلاتر عدا مستوى واحد (حتى الأعداد تكون صحيحة لكل مستوى)
function mfMatch(u, skip) {
  const st = fixState(u);
  if (skip !== 'team' && MF.team.length && MF.team.indexOf(uTeam(u)) < 0) return false;
  if (skip !== 'sup' && MF.sup.length && MF.sup.indexOf(uSup(u)) < 0) return false;
  if (skip !== 'page' && MF.page.length && MF.page.indexOf(uPage(u)) < 0) return false;
  if (skip !== 'range' && MF.range.length && MF.range.indexOf(u.rangeKey || UNC) < 0) return false;
  if (skip !== 'status' && MF.status.length && !MF.status.some(k => MF_STATUS.find(x => x.k === k).t(st))) return false;
  if (skip !== 'perm' && MF.perm.length && !MF.perm.some(k => u.permissions && u.permissions[k])) return false;
  if (MF.q) {
    const hay = nk([u.email, u.username, u.mobile, u.pageName, u.supervisor, u.updatedBy].join(' '));
    if (!MF.q.split(' ').every(w => hay.includes(w))) return false;
  }
  return true;
}
function mfCount(level, fn) {
  const m = {};
  allUsers.forEach(u => { if (mfMatch(u, level)) fn(u).forEach(v => m[v] = (m[v] || 0) + 1); });
  return m;
}
function mfToggle(level, v) {
  const a = MF[level], i = a.indexOf(v);
  if (i > -1) a.splice(i, 1); else a.push(v);
  mfSave(); applyFilters();
}
function mfSet(level, arr) { MF[level] = arr; mfSave(); applyFilters(); }
function mfClear() { MF = { team: [], sup: [], page: [], range: [], status: [], perm: [], q: '' }; document.getElementById('search-input').value = ''; mfSave(); applyFilters(); }
let mfT;
function onSearch(v) { clearTimeout(mfT); mfT = setTimeout(() => { MF.q = nk(v); mfSave(); applyFilters(); }, 150); }
function esc(v) { return String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function jsq(v) { return esc(JSON.stringify(v)); }

function mfChips(level, opts, cls) {
  // opts: [{k, l, n, c}]
  const lim = 14, showAll = MF_MORE[level];
  const sel = MF[level];
  let list = opts.filter(o => o.n > 0 || sel.indexOf(o.k) > -1);
  const hidden = !showAll && list.length > lim ? list.length - lim : 0;
  if (hidden) list = list.filter((o, i) => i < lim || sel.indexOf(o.k) > -1);
  let h = `<button class="mf-chip ${sel.length ? '' : 'on'}" onclick='mfSet("${level}", [])'>الكل</button>`;
  list.forEach(o => {
    h += `<button class="mf-chip ${o.c ? 'st-' + o.c : ''} ${sel.indexOf(o.k) > -1 ? 'on' : ''} ${o.n ? '' : 'zero'}" onclick='mfToggle("${level}", ${jsq(o.k)})'>${esc(o.l)}<b>${o.n}</b></button>`;
  });
  if (hidden) h += `<button class="mf-more" onclick="MF_MORE['${level}']=1;applyFilters()">+ ${hidden} أكثر</button>`;
  return h;
}
function mfOrder(m, order) {
  const keys = Object.keys(m);
  keys.sort((a, b) => {
    if (a === UNC) return 1; if (b === UNC) return -1;
    const ia = order.indexOf(a), ib = order.indexOf(b);
    if (ia > -1 || ib > -1) return (ia < 0 ? 999 : ia) - (ib < 0 ? 999 : ib);
    return m[b] - m[a];
  });
  return keys;
}

