    card('ok', cnt('ok'), 'سليم', 'green');

  // شريط الفلاتر الفعّالة
  const names = { team: 'الفريق', sup: 'المشرفة', page: 'الصفحة', range: 'النطاق', status: 'الحالة', perm: 'الصلاحية' };
