// توحيد الكتابة العربية للبحث والمطابقة
function nk(v) {
  return String(v || '').toLowerCase()
    .replace(/[ً-ْـ]/g, '')
    .replace(/[أإآٱ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي')
    .replace(/ؤ/g, 'و').replace(/ئ/g, 'ي').replace(/ء/g, '')
    .replace(/\s+/g, ' ').trim();
}

function loadPickLists() {
  google.script.run
    .withSuccessHandler(function(r) {
      if (!r || !r.success) return;
      PICK = Object.assign(PICK, r, { loaded: true });
      PICK.pageSet = new Set(r.pages.map(p => p.name));
      PICK.supSet = new Set(r.supervisors);
      fillPageSelect(document.getElementById('manual-pagename'), '— اختاري الصفحة —');
      fillSupSelect(document.getElementById('manual-supervisor'), '— اختاري المشرفة —');
      const mp = document.getElementById('manual-pagename');
      mp.addEventListener('change', function() {
        const pg = PICK.pages.find(p => p.name === this.value);
        const ms = document.getElementById('manual-supervisor');
        if (pg && PICK.supSet.has(pg.supervisor) && !ms.value) ms.value = pg.supervisor;
      });
      if (allUsers.length) applyFilters();
    })
    .withFailureHandler(function(e) { console.error('pick lists', e); })
    .getPickLists();
}

function fillPageSelect(sel, placeholder) {
  const groups = {};
  PICK.pages.forEach(p => { const g = p.group || p.supervisor; (groups[g] = groups[g] || []).push(p.name); });
  let h = `<option value="">${placeholder}</option>`;
  Object.keys(groups).forEach(g => {
    h += `<optgroup label="${g}">` + groups[g].map(n => `<option value="${n}">${n}</option>`).join('') + '</optgroup>';
  });
  sel.innerHTML = h;
}
function fillSupSelect(sel, placeholder) {
  sel.innerHTML = `<option value="">${placeholder}</option>` +
    PICK.supervisors.map(n => `<option value="${n}">${n}${PICK.managers && PICK.managers[n] ? ' (تحت ' + PICK.managers[n] + ')' : ''}</option>`).join('');
}

function fixState(user) {
  if (!PICK.loaded) return { page: false, sup: false, delegate: false };
  const pg = String(user.pageName || '').trim(), sp = String(user.supervisor || '').trim();
  const pgItem = PICK.pages.find(p => p.name === pg);
  // ⚠️ المشرفة المكتوبة ما تطابق مشرفة الصفحة بالقائمة (مثلاً الصفحة انتقلت لمشرفة ثانية)
  const mismatch = !!(pgItem && PICK.supSet.has(pgItem.supervisor) && PICK.supSet.has(sp) && sp !== pgItem.supervisor);
  return {
    page: !PICK.pageSet.has(pg),
    sup: !PICK.supSet.has(sp) || mismatch,
    mismatch: mismatch,
    expected: mismatch ? pgItem.supervisor : '',
    delegate: PICK.delegateNames.some(d => nk(d) === nk(sp))
  };
}

// اقتراح الاسم الصحيح من الكتابة القديمة
function suggestPage(raw) {
  const k = nk(raw);
  if (!k) return '';
  const exact = PICK.pages.find(p => nk(p.name) === k);
  if (exact) return exact.name;
  for (const a in PICK.aliases) if (nk(a) === k && PICK.pageSet.has(PICK.aliases[a])) return PICK.aliases[a];
  const part = PICK.pages.filter(p => nk(p.name).includes(k) || k.includes(nk(p.name)));
  return part.length === 1 ? part[0].name : '';
}
function suggestSup(raw, pageName) {
  const k = nk(raw);
  const exact = PICK.supervisors.find(s => nk(s) === k);
  if (exact) return exact;
  for (const a in PICK.aliases) if (nk(a) === k && PICK.supSet.has(PICK.aliases[a])) return PICK.aliases[a];
  const pg = PICK.pages.find(p => p.name === pageName);
  return pg && PICK.supSet.has(pg.supervisor) ? pg.supervisor : '';
}

function openFixModal(rowIndex, srcUser) {
  if (!PICK.loaded) { alert('القوائم بعدها تتحمل، ثواني وحاولي مرة ثانية'); return; }
