  if (!user) return;
  fixTarget = { mode: srcUser ? 'add' : 'edit', user: user };
  document.getElementById('fix-email').textContent = user.email;
  document.getElementById('fix-username').textContent = user.username || '—';
  document.getElementById('fix-old-page').textContent = user.pageName || '—';
  document.getElementById('fix-old-sup').textContent = user.supervisor || '—';
  const ps = document.getElementById('fix-page'), ss = document.getElementById('fix-sup');
  fillPageSelect(ps, '— اختاري الصفحة —');
  fillSupSelect(ss, '— اختاري المشرفة —');
  const sp = suggestPage(user.pageName);
  ps.value = sp;
  ss.value = fixState(user).mismatch ? fixState(user).expected : suggestSup(user.supervisor, sp);
  document.getElementById('fix-hint').textContent = fixState(user).delegate
    ? '«' + user.supervisor + '» مندوبة مو مشرفة — اختاري المشرفة الصحيحة' : '';
  document.getElementById('fix-save-btn').textContent = fixTarget.mode === 'add' ? '✓ صحّح وأضف' : '✓ حفظ التصحيح';
  document.getElementById('fixModal').style.display = 'block';
}
